{
  "a_sentences": [
    {
      "a_text": "L'arrêt entrepris expose les dispositions légales et principes jurisprudentiels applicables à la notion d'invalidité, à son évaluation et à la révision du droit à la rente.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le droit au reclassement suppose que l'invalidité rend la mesure nécessaire et que la capacité de gain peut ainsi être maintenue ou améliorée.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "La notion d'équivalence approximative entre l'activité antérieure et l'activité envisagée se réfère aux perspectives de gain après la réadaptation, non au niveau de formation en soi.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Une formation prise en charge ne suffit pas si elle ne procure pas un revenu satisfaisant, nécessitant des mesures supplémentaires pour obtenir un gain comparable à celui de l'activité antérieure.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Pour la période du 1er août 2012 au 31 décembre 2012, le taux d'invalidité de la personne assurée a été fixé à 60 % en application de la méthode mixte.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "À compter du 1er avril 2019, la juridiction cantonale a fixé le taux d'invalidité à 38 %, insuffisant pour maintenir le droit à une rente.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que le calcul du taux d'invalidité aboutit au même résultat, qu'il s'agisse de la profession de spécialiste en insertion professionnelle ou d'assistante sociale.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "La juridiction cantonale retient que la personne assurée a déjà bénéficié de mesures de reclassement, notamment un CAS de spécialiste en insertion professionnelle et un certificat de formatrice d'adulte.",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "Le Tribunal fédéral conclut que ces mesures sont suffisantes pour maintenir une capacité de gain approximativement équivalente à celle de l'activité d'infirmière spécialisée exercée avant l'invalidité.",
      "b_propositions": ["P7", "P8"]
    }
  ]
}
